5)\n    assert not thread.is_alive()\n    assert errors == []\n    assert worker_conn_id is not None\n    assert worker_conn_id != id(main_conn)\n    factory.close_thread_connection()\n","isEmpty":false,"exceededLimit":false,"totalLines":55,"fileSize":1782,"path":"/home/sean/Documents/experiments/csw-041026/.dreadnought/scratch/koffer/work/tests/unit/test_connection_factory.py","readRange":{"startLine":1,"endLine":55},"relatedCursorRulePaths":[],"relatedCursorRules":[]}}},"hookAdditionalContexts":[],"toolCallId":"call-776cb0b0-4a09-4ebb-8c3c-3e2817be6011-34\nfc_p3vRMDs-3LYxF7-3d52bb41-aws_ue1_2","startedAtMs":"1791145797313","completedAtMs":"1791145797499"},"model_call_id":"899a6a77-1cad-4acb-823b-3633a1af8ed3-6-w9fj","session_id":"3ac07d88-4516-42c6-b14d-0482f3a10c69","timestamp_ms":1791145797469}
