 ?, ?, ?, ?, ?, ?, ?)\n            \"\"\",\n            (\n                str(source.id),\n                source.display_name,\n                source.root_path,\n                source.storage_fingerprint,\n                bool_to_int(source.enabled),\n                bool_to_int(source.recursive),\n                str(source.status),\n                source.last_scan_started_at,\n                source.last_scan_completed_at,\n                source.last_seen_at,\n                source.created_at,\n                source.updated_at,\n            ),\n        )\n\n    def get(self, source_id: EntityId) -> Source | None:\n        row = self._conn.execute(\n            \"SELECT * FROM sources WHERE id = ?\",\n            (str(source_id),),\n        ).fetchone()\n        return None if row is None else _from_row(row)\n\n    def list_all(self) -> list[Source]:\n        rows = self._conn.execute(\n            \"SELECT * FROM sources ORDER BY created_at ASC, id ASC\"\n        ).fetchall()\n        return [_from_row(row) for row in rows]\n\n    def update(self, source: Source) -> bool:\n        return (\n            row_count(\n                self._conn,\n                \"\"\"\n                UPDATE sources SET\n                    display_name = ?,\n                    root_path = ?,\n                    storage_fingerprint = ?,\n                    enabled = ?,\n                    recursive = ?,\n                    status = ?,\n                    last_scan_started_at = ?,\n                    last_scan_completed_at = ?,\n                    last_seen_at = ?,\n                    updated_at = ?\n                WHERE id = ?\n                \"\"\",\n                (\n                    source.display_name,\n                    source.root_path,\n                    source.storage_fingerprint,\n                    bool_to_int(source.enabled),\n                    bool_to_int(source.recursive),\n                    str(source.status),\n                    source.last_scan_started_at,\n                    source.last_scan_completed_at,\n                    source.last_seen_at,\n                    source.updated_at,\n                    str(source.id),\n                ),\n            )\n            > 0\n        )\n\n    def delete(self, source_id: EntityId) -> bool:\n        return (\n            row_count(\n                self._conn,\n                \"DELETE FROM sources WHERE id = ?\",\n                (str(source_id),),\n            )\n            > 0\n        )\n"}},"hookAdditionalContexts":[],"toolCallId":"call-6513ac12-9944-46ae-8370-7f4e50c416cc-40\nfc_p3vRR84-3LYxF7-c01f1db5-aws_ue1_1","startedAtMs":"1791145803049"},"model_call_id":"899a6a77-1cad-4acb-823b-3633a1af8ed3-8-b04d","session_id":"3ac07d88-4516-42c6-b14d-0482f3a10c69","timestamp_ms":1791145806893}
